DROP PROCEDURE IF EXISTS add_migration;
DELIMITER ??
CREATE PROCEDURE `add_migration`()
BEGIN
DECLARE v INT DEFAULT 1;
SET v = (SELECT COUNT(*) FROM `migrations` WHERE `id`='20261019500000');
IF v = 0 THEN

DELETE FROM `bonk_mob_ability` WHERE `entry` IN (639, 642, 1763, 11982, 11988, 12056, 4421, 4422, 3654, 412, 1200, 314, 14834, 14509, 11382, 15339, 15205, 7273, 7267, 6584, 10041, 680, 1061, 12201, 12225, 13596, 2748, 7023, 7206, 2611, 2779, 8443, 5710, 5719, 9019, 10363, 10440, 10813, 1853, 10503, 11261, 11486, 11501, 10429, 10430, 12397, 14467, 7800, 6228);

END IF;
END??
DELIMITER ;
CALL add_migration();
DROP PROCEDURE IF EXISTS add_migration;
